def _node_contains_key(node, key: str) -> bool:
    """Return whether any dict in node's tree contains key."""
    if isinstance(node, dict):
        if key in node:
            return True
        return any(_node_contains_key(value, key) for value in node.values())
    if isinstance(node, list):
        return any(_node_contains_key(item, key) for item in node)
    return False


